"use client";

import "./popover.css";

import { useEffect, useState, type ComponentProps, type ReactNode } from "react";
import { placeFromInvoker, popoverAnchorStyle, triggerAnchorStyle } from "./anchor";
import { Button, type ButtonVariant } from "./button";
import { cx } from "./cx";

export type PopoverProps = ComponentProps<"div">;

export type PopoverTriggerProps = {
  popoverTarget: string;
  children?: ReactNode;
  className?: string | undefined;
  variant?: ButtonVariant | undefined;
  disabled?: boolean | undefined;
};

export function Popover({ className, id, style, ...rest }: PopoverProps) {
  return (
    <div
      {...rest}
      id={id}
      popover="auto"
      className={cx("ns-popover", className)}
      style={{ ...popoverAnchorStyle(id), ...style }}
    />
  );
}

export function PopoverTrigger({
  popoverTarget,
  children,
  className,
  variant = "outline",
  disabled,
}: PopoverTriggerProps) {
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    const node = document.getElementById(popoverTarget);
    if (!node) return;
    const onToggle = (event: Event) => {
      const open =
        "newState" in event && (event as ToggleEvent).newState === "open";
      setExpanded(open);
      if (open) placeFromInvoker(node);
    };
    node.addEventListener("toggle", onToggle);
    setExpanded(node.matches(":popover-open"));
    if (node.matches(":popover-open")) placeFromInvoker(node);
    return () => node.removeEventListener("toggle", onToggle);
  }, [popoverTarget]);

  return (
    <Button
      variant={variant}
      className={className}
      popoverTarget={popoverTarget}
      style={triggerAnchorStyle(popoverTarget)}
      aria-haspopup="true"
      aria-expanded={expanded}
      aria-controls={popoverTarget}
      {...(disabled ? { disabled: true } : {})}
    >
      {children}
    </Button>
  );
}

@layer components {
  .ns-popover {
    box-sizing: border-box;
    min-width: 10rem;
    width: max-content;
    inset: unset;
    margin: 0;
    margin-block-start: var(--space-3, 0.39rem);
    padding: var(--inset-list, var(--space-2, 0.31rem));
    border: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 18%, transparent));
    border-radius: var(--radius-list, calc(var(--radius, 0.4rem) + var(--space-2, 0.31rem)));
    background: var(--bg-overlay, var(--bg, #fff));
    color: var(--text-body, #444);
    box-shadow: none;
  }

  @supports (top: anchor(bottom)) {
    .ns-popover {
      top: anchor(bottom);
      inset-inline-start: anchor(start);
    }
  }

  .ns-popover:popover-open {
    z-index: var(--z-overlay, 20);
  }
}

import type { CSSProperties } from "react";

function ident(id: string) {
  return `--ns-${id.replace(/[^a-zA-Z0-9_-]/g, "")}`;
}

export function triggerAnchorStyle(id: string): CSSProperties {
  return { anchorName: ident(id) } as CSSProperties;
}

export function popoverAnchorStyle(id: string | undefined): CSSProperties {
  if (!id) return {};
  return { positionAnchor: ident(id) } as CSSProperties;
}

export function supportsAnchorPosition() {
  return (
    typeof CSS !== "undefined" &&
    (CSS.supports("position-area: block-end") ||
      CSS.supports("top: anchor(bottom)"))
  );
}

export function placeFromInvoker(node: HTMLElement) {
  if (!node.id || supportsAnchorPosition()) return;
  const invoker = document.querySelector(
    `[popovertarget="${CSS.escape(node.id)}"]`,
  );
  if (!(invoker instanceof HTMLElement)) return;
  const rect = invoker.getBoundingClientRect();
  node.style.top = `${Math.round(rect.bottom + 6)}px`;
  node.style.left = `${Math.round(rect.left)}px`;
}
